#if BUILDFLAG(IS_MAC)
void FirefoxImporter::ImportPasswords() {
  // Destroy the NSS/database snapshot before publishing the utility result.
  const auto result = [this]() -> std::pair<bool, uint32_t> {
    const auto json_file = source_path_.AppendASCII("logins.json");
    if (!base::PathExists(json_file))
      return {true, 0};
    NSSDecryptor decryptor;
    if (!decryptor.Init(source_path_, source_path_) &&
        !decryptor.Init(app_path_, source_path_) &&
        !decryptor.Init(base::FilePath("/Applications/Firefox.app/Contents/MacOS"),
                        source_path_)) {
      return {false, 0};
    }
    std::vector<user_data_importer::ImportedPasswordForm> forms;
    if (!decryptor.ReadAndParseLogins(json_file, &forms))
      return {false, 0};
    size_t forwarded = 0;
    for (const auto& form : forms) {
      if (cancelled())
        return {false, 0};
      if (!form.username_value.empty() || !form.password_value.empty() ||
          form.blocked_by_user) {
        bridge_->SetPasswordForm(form);
        ++forwarded;
      }
    }
    if (!forms.empty() && forwarded == 0)
      return {false, 0};
    return {true, base::checked_cast<uint32_t>(forwarded)};
  }();
  bridge_->NotifyFirefoxPasswordImportResult(result.first, result.second);
}
